Q: How to force download of &quot;index.html&quot; file via an &lt;a&gt; tag in HTML A: <pre><code>&lt;!DOCTYPE html&gt;
&lt;html lang=&quot;en&quot;&gt;
&lt;head&gt;
  &lt;meta charset=&quot;UTF-8&quot;&gt;
  &lt;meta name=&quot;viewport&quot; content=&quot;width=device-width, initial-scale=1.0&quot;&gt;

  &lt;title&gt;S Cool Service Center | Home Appliance Repair in Mumbai&lt;/title&gt;
  &lt;meta name=&quot;description&quot; content=&quot;S Cool Service Center provides reliable home appliance repair and service in Mumbai. Call or WhatsApp 8097301783.&quot;&gt;

  &lt;style&gt;
    * {
      margin: 0;
      padding: 0;
      box-sizing: border-box;
      scroll-behavior: smooth;
    }

    body {
      font-family: Arial, Helvetica, sans-serif;
      background: #f5f9fc;
      color: #17212b;
      line-height: 1.6;
    }

    header {
      background: linear-gradient(135deg, #0066ff, #00b7ff);
      color: white;
      padding: 18px 6%;
      position: sticky;
      top: 0;
      z-index: 1000;
      box-shadow: 0 3px 15px rgba(0,0,0,0.15);
    }

    .navbar {
      max-width: 1200px;
      margin: auto;
      display: flex;
      justify-content: space-between;
      align-items: center;
    }

    .logo {
      font-size: 25px;
      font-weight: 800;
    }

    .logo span {
      color: #ffe600;
    }

    nav a {
      color: white;
      text-decoration: none;
      margin-left: 22px;
      font-weight: 600;
    }

    nav a:hover {
      color: #ffe600;
    }

    .hero {
      min-height: 650px;
      display: flex;
      align-items: center;
      background:
        linear-gradient(rgba(0,80,160,.82), rgba(0,30,70,.82)),
        url(&quot;https://images.unsplash.com/photo-1581578731548-c64695cc6952?auto=format&amp;fit=crop&amp;w=1600&amp;q=80&quot;)
        center/cover;
      color: white;
      padding: 80px 6%;
    }

    .hero-content {
      max-width: 1200px;
      margin: auto;
      width: 100%;
    }

    .hero h1 {
      font-size: clamp(40px, 6vw, 72px);
      line-height: 1.05;
      max-width: 750px;
      margin-bottom: 22px;
    }

    .hero h1 span {
      color: #ffe600;
    }

    .hero p {
      font-size: 20px;
      max-width: 650px;
      margin-bottom: 32px;
    }

    .buttons {
      display: flex;
      gap: 15px;
      flex-wrap: wrap;
    }

    .btn {
      display: inline-block;
      padding: 14px 25px;
      border-radius: 8px;
      text-decoration: none;
      font-weight: 700;
      border: none;
      cursor: pointer;
      font-size: 16px;
      transition: .3s;
    }

    .btn-primary {
      background: #ffe600;
      color: #111;
    }

    .btn-primary:hover {
      transform: translateY(-3px);
      background: white;
    }

    .btn-whatsapp {
      background: #25D366;
      color: white;
    }

    .btn-whatsapp:hover {
      transform: translateY(-3px);
    }

    section {
      padding: 75px 6%;
    }

    .section-title {
      text-align: center;
      margin-bottom: 45px;
    }

    .section-title h2 {
      font-size: 38px;
      color: #0756b8;
      margin-bottom: 10px;
    }

    .section-title p {
      color: #66717d;
    }

    .services {
      max-width: 1200px;
      margin: auto;
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 25px;
    }

    .service-card {
      background: white;
      padding: 32px 25px;
      border-radius: 15px;
      text-align: center;
      box-shadow: 0 5px 25px rgba(0,0,0,.08);
      transition: .3s;
    }

    .service-card:hover {
      transform: translateY(-8px);
      box-shadow: 0 12px 30px rgba(0,0,0,.14);
    }

    .service-icon {
      font-size: 50px;
      margin-bottom: 15px;
    }

    .service-card h3 {
      color: #0756b8;
      margin-bottom: 10px;
      font-size: 22px;
    }

    .about {
      background: white;
    }

    .about-container {
      max-width: 1100px;
      margin: auto;
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 50px;
      align-items: center;
    }

    .about-image img {
      width: 100%;
      border-radius: 18px;
      box-shadow: 0 8px 30px rgba(0,0,0,.15);
    }

    .about-text h2 {
      color: #0756b8;
      font-size: 38px;
      margin-bottom: 18px;
    }

    .features {
      margin-top: 25px;
      display: grid;
      gap: 12px;
    }

    .feature {
      font-weight: 600;
    }

    .booking {
      background: linear-gradient(135deg, #0066ff, #00a8e8);
    }

    .booking-container {
      max-width: 700px;
      margin: auto;
      background: white;
      padding: 35px;
      border-radius: 18px;
      box-shadow: 0 10px 35px rgba(0,0,0,.18);
    }

    .booking-container h2 {
      text-align: center;
      color: #0756b8;
      margin-bottom: 25px;
      font-size: 32px;
    }

    .form-group {
      margin-bottom: 18px;
    }

    .form-group label {
      display: block;
      font-weight: 700;
      margin-bottom: 7px;
    }

    .form-group input,
    .form-group select,
    .form-group textarea {
      width: 100%;
      padding: 13px;
      border: 1px solid #ccd5dd;
      border-radius: 7px;
      font-size: 16px;
      outline: none;
    }

    .form-group input:focus,
    .form-group select:focus,
    .form-group textarea:focus {
      border-color: #0066ff;
    }

    textarea {
      resize: vertical;
      min-height: 100px;
    }

    .submit-btn {
      width: 100%;
      background: #0756b8;
      color: white;
      padding: 15px;
      border: none;
      border-radius: 8px;
      font-size: 17px;
      font-weight: 700;
      cursor: pointer;
    }

    .submit-btn:hover {
      background: #003d86;
    }

    .contact {
      background: #f5f9fc;
    }

    .contact-container {
      max-width: 1000px;
      margin: auto;
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 25px;
    }

    .contact-card {
      background: white;
      padding: 30px 20px;
      text-align: center;
      border-radius: 15px;
      box-shadow: 0 5px 20px rgba(0,0,0,.07);
    }

    .contact-card .icon {
      font-size: 38px;
      margin-bottom: 10px;
    }

    .contact-card h3 {
      color: #0756b8;
      margin-bottom: 7px;
    }

    .contact-card a {
      color: #17212b;
      text-decoration: none;
      font-weight: 600;
    }

    footer {
      background: #071a2e;
      color: white;
      text-align: center;
      padding: 28px 15px;
    }

    footer strong {
      color: #ffe600;
    }

    .floating-buttons {
      position: fixed;
      right: 18px;
      bottom: 18px;
      display: flex;
      flex-direction: column;
      gap: 10px;
      z-index: 999;
    }

    .floating-buttons a {
      width: 54px;
      height: 54px;
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      text-decoration: none;
      color: white;
      font-size: 25px;
      box-shadow: 0 4px 15px rgba(0,0,0,.25);
    }

    .call {
      background: #0066ff;
    }

    .whatsapp {
      background: #25D366;
    }

    @media (max-width: 850px) {
      nav {
        display: none;
      }

      .services {
        grid-template-columns: repeat(2, 1fr);
      }

      .about-container {
        grid-template-columns: 1fr;
      }

      .contact-container {
        grid-template-columns: 1fr;
      }
    }

    @media (max-width: 550px) {
      .hero {
        min-height: 600px;
      }

      .services {
        grid-template-columns: 1fr;
      }

      section {
        padding: 55px 5%;
      }

      .booking-container {
        padding: 25px 18px;
      }

      .hero p {
        font-size: 17px;
      }
    }
  &lt;/style&gt;
&lt;/head&gt;

&lt;body&gt;

&lt;header&gt;
  &lt;div class=&quot;navbar&quot;&gt;
    &lt;div class=&quot;logo&quot;&gt;S &lt;span&gt;Cool&lt;/span&gt; Service Center&lt;/div&gt;

    &lt;nav&gt;
      &lt;a href=&quot;#home&quot;&gt;Home&lt;/a&gt;
      &lt;a href=&quot;#services&quot;&gt;Services&lt;/a&gt;
      &lt;a href=&quot;#about&quot;&gt;About&lt;/a&gt;
      &lt;a href=&quot;#booking&quot;&gt;Book Service&lt;/a&gt;
      &lt;a href=&quot;#contact&quot;&gt;Contact&lt;/a&gt;
    &lt;/nav&gt;
  &lt;/div&gt;
&lt;/header&gt;


&lt;!-- HERO --&gt;
&lt;section class=&quot;hero&quot; id=&quot;home&quot;&gt;
  &lt;div class=&quot;hero-content&quot;&gt;

    &lt;h1&gt;
      Reliable Home Appliance
      &lt;span&gt;Service in Mumbai&lt;/span&gt;
    &lt;/h1&gt;

    &lt;p&gt;
      Fast, professional and affordable repair services for your home appliances.
      Book a service today with S Cool Service Center.
    &lt;/p&gt;

    &lt;div class=&quot;buttons&quot;&gt;
      &lt;a class=&quot;btn btn-primary&quot; href=&quot;#booking&quot;&gt;
        🔧 Book a Service
      &lt;/a&gt;

      &lt;a class=&quot;btn btn-whatsapp&quot;
         href=&quot;https://wa.me/918097301783?text=Hello%20S%20Cool%20Service%20Center%2C%20I%20need%20appliance%20service.&quot;
         target=&quot;_blank&quot;&gt;
        💬 WhatsApp Us
      &lt;/a&gt;
    &lt;/div&gt;

  &lt;/div&gt;
&lt;/section&gt;


&lt;!-- SERVICES --&gt;
&lt;section id=&quot;services&quot;&gt;
  &lt;div class=&quot;section-title&quot;&gt;
    &lt;h2&gt;Our Services&lt;/h2&gt;
    &lt;p&gt;Professional repair and maintenance for your home appliances.&lt;/p&gt;
  &lt;/div&gt;

  &lt;div class=&quot;services&quot;&gt;

    &lt;div class=&quot;service-card&quot;&gt;
      &lt;div class=&quot;service-icon&quot;&gt;❄️&lt;/div&gt;
      &lt;h3&gt;AC Service&lt;/h3&gt;
      &lt;p&gt;AC repair, servicing, installation and maintenance.&lt;/p&gt;
    &lt;/div&gt;

    &lt;div class=&quot;service-card&quot;&gt;
      &lt;div class=&quot;service-icon&quot;&gt;🧊&lt;/div&gt;
      &lt;h3&gt;Refrigerator&lt;/h3&gt;
      &lt;p&gt;Refrigerator repair and cooling problem solutions.&lt;/p&gt;
    &lt;/div&gt;

    &lt;div class=&quot;service-card&quot;&gt;
      &lt;div class=&quot;service-icon&quot;&gt;🧺&lt;/div&gt;
      &lt;h3&gt;Washing Machine&lt;/h3&gt;
      &lt;p&gt;Repair and maintenance for washing machines.&lt;/p&gt;
    &lt;/div&gt;

    &lt;div class=&quot;service-card&quot;&gt;
      &lt;div class=&quot;service-icon&quot;&gt;🔥&lt;/div&gt;
      &lt;h3&gt;Microwave Oven&lt;/h3&gt;
      &lt;p&gt;Microwave inspection, repair and maintenance.&lt;/p&gt;
    &lt;/div&gt;

    &lt;div class=&quot;service-card&quot;&gt;
      &lt;div class=&quot;service-icon&quot;&gt;🚿&lt;/div&gt;
      &lt;h3&gt;Geyser&lt;/h3&gt;
      &lt;p&gt;Geyser repair, installation and maintenance.&lt;/p&gt;
    &lt;/div&gt;

    &lt;div class=&quot;service-card&quot;&gt;
      &lt;div class=&quot;service-icon&quot;&gt;🔧&lt;/div&gt;
      &lt;h3&gt;Other Appliances&lt;/h3&gt;
      &lt;p&gt;Contact us for other home appliance repair requirements.&lt;/p&gt;
    &lt;/div&gt;

  &lt;/div&gt;
&lt;/section&gt;


&lt;!-- ABOUT --&gt;
&lt;section class=&quot;about&quot; id=&quot;about&quot;&gt;

  &lt;div class=&quot;about-container&quot;&gt;

    &lt;div class=&quot;about-image&quot;&gt;
      &lt;img
        src=&quot;https://images.unsplash.com/photo-1581094794329-c8112a89af12?auto=format&amp;fit=crop&amp;w=1000&amp;q=80&quot;
        alt=&quot;Home appliance technician&quot;&gt;
    &lt;/div&gt;

    &lt;div class=&quot;about-text&quot;&gt;
      &lt;h2&gt;Why Choose S Cool?&lt;/h2&gt;

      &lt;p&gt;
        S Cool Service Center provides dependable home appliance repair
        and maintenance services in Mumbai.
      &lt;/p&gt;

      &lt;div class=&quot;features&quot;&gt;
        &lt;div class=&quot;feature&quot;&gt;✅ Professional Service&lt;/div&gt;
        &lt;div class=&quot;feature&quot;&gt;✅ Fast Response&lt;/div&gt;
        &lt;div class=&quot;feature&quot;&gt;✅ Affordable Pricing&lt;/div&gt;
        &lt;div class=&quot;feature&quot;&gt;✅ Home Service Available&lt;/div&gt;
        &lt;div class=&quot;feature&quot;&gt;✅ Customer Satisfaction&lt;/div&gt;
      &lt;/div&gt;
    &lt;/div&gt;

  &lt;/div&gt;

&lt;/section&gt;


&lt;!-- BOOKING --&gt;
&lt;section class=&quot;booking&quot; id=&quot;booking&quot;&gt;

  &lt;div class=&quot;booking-container&quot;&gt;

    &lt;h2&gt;Book a Service&lt;/h2&gt;

    &lt;form id=&quot;bookingForm&quot;&gt;

      &lt;div class=&quot;form-group&quot;&gt;
        &lt;label for=&quot;name&quot;&gt;Your Name&lt;/label&gt;
        &lt;input type=&quot;text&quot; id=&quot;name&quot; placeholder=&quot;Enter your name&quot; required&gt;
      &lt;/div&gt;

      &lt;div class=&quot;form-group&quot;&gt;
        &lt;label for=&quot;phone&quot;&gt;Phone Number&lt;/label&gt;
        &lt;input
          type=&quot;tel&quot;
          id=&quot;phone&quot;
          placeholder=&quot;Enter phone number&quot;
          pattern=&quot;[0-9]{10}&quot;
          required&gt;
      &lt;/div&gt;

      &lt;div class=&quot;form-group&quot;&gt;
        &lt;label for=&quot;appliance&quot;&gt;Select Appliance&lt;/label&gt;

        &lt;select id=&quot;appliance&quot; required&gt;
          &lt;option value=&quot;&quot;&gt;Choose appliance&lt;/option&gt;
          &lt;option&gt;AC&lt;/option&gt;
          &lt;option&gt;Refrigerator&lt;/option&gt;
          &lt;option&gt;Washing Machine&lt;/option&gt;
          &lt;option&gt;Microwave Oven&lt;/option&gt;
          &lt;option&gt;Geyser&lt;/option&gt;
          &lt;option&gt;Other&lt;/option&gt;
        &lt;/select&gt;
      &lt;/div&gt;

      &lt;div class=&quot;form-group&quot;&gt;
        &lt;label for=&quot;problem&quot;&gt;Describe the Problem&lt;/label&gt;

        &lt;textarea
          id=&quot;problem&quot;
          placeholder=&quot;Tell us about the appliance problem...&quot;
          required&gt;&lt;/textarea&gt;
      &lt;/div&gt;

      &lt;button class=&quot;submit-btn&quot; type=&quot;submit&quot;&gt;
        📲 Send Booking on WhatsApp
      &lt;/button&gt;

    &lt;/form&gt;

  &lt;/div&gt;

&lt;/section&gt;


&lt;!-- CONTACT --&gt;
&lt;section class=&quot;contact&quot; id=&quot;contact&quot;&gt;

  &lt;div class=&quot;section-title&quot;&gt;
    &lt;h2&gt;Contact Us&lt;/h2&gt;
    &lt;p&gt;Get in touch with S Cool Service Center.&lt;/p&gt;
  &lt;/div&gt;

  &lt;div class=&quot;contact-container&quot;&gt;

    &lt;div class=&quot;contact-card&quot;&gt;
      &lt;div class=&quot;icon&quot;&gt;📞&lt;/div&gt;
      &lt;h3&gt;Call Us&lt;/h3&gt;
      &lt;a href=&quot;tel:8097301783&quot;&gt;8097301783&lt;/a&gt;
    &lt;/div&gt;

    &lt;div class=&quot;contact-card&quot;&gt;
      &lt;div class=&quot;icon&quot;&gt;💬&lt;/div&gt;
      &lt;h3&gt;WhatsApp&lt;/h3&gt;
      &lt;a href=&quot;https://wa.me/918097301783&quot; target=&quot;_blank&quot;&gt;
        Chat on WhatsApp
      &lt;/a&gt;
    &lt;/div&gt;

    &lt;div class=&quot;contact-card&quot;&gt;
      &lt;div class=&quot;icon&quot;&gt;📍&lt;/div&gt;
      &lt;h3&gt;Service Area&lt;/h3&gt;
      &lt;p&gt;Mumbai, Maharashtra&lt;/p&gt;
    &lt;/div&gt;

  &lt;/div&gt;

&lt;/section&gt;


&lt;!-- FOOTER --&gt;
&lt;footer&gt;
  &lt;p&gt;
    © &lt;span id=&quot;year&quot;&gt;&lt;/span&gt;
    &lt;strong&gt;S Cool Service Center&lt;/strong&gt;.
    All Rights Reserved.
  &lt;/p&gt;

  &lt;p&gt;Home Appliance Service in Mumbai&lt;/p&gt;
&lt;/footer&gt;


&lt;!-- FLOATING BUTTONS --&gt;
&lt;div class=&quot;floating-buttons&quot;&gt;

  &lt;a class=&quot;call&quot; href=&quot;tel:8097301783&quot; title=&quot;Call&quot;&gt;
    📞
  &lt;/a&gt;

  &lt;a class=&quot;whatsapp&quot;
     href=&quot;https://wa.me/918097301783&quot;
     target=&quot;_blank&quot;
     title=&quot;WhatsApp&quot;&gt;
    💬
  &lt;/a&gt;

&lt;/div&gt;


&lt;script&gt;

  // Current year
  document.getElementById(&quot;year&quot;).textContent =
    new Date().getFullYear();


  // WhatsApp booking form
  document.getElementById(&quot;bookingForm&quot;).addEventListener(&quot;submit&quot;, function(e) {

    e.preventDefault();

    const name =
      document.getElementById(&quot;name&quot;).value.trim();

    const phone =
      document.getElementById(&quot;phone&quot;).value.trim();

    const appliance =
      document.getElementById(&quot;appliance&quot;).value;

    const problem =
      document.getElementById(&quot;problem&quot;).value.trim();


    const message =
      &quot;Hello S Cool Service Center,%0A%0A&quot; +
      &quot;I want to book a service.%0A%0A&quot; +
      &quot;Name: &quot; + encodeURIComponent(name) + &quot;%0A&quot; +
      &quot;Phone: &quot; + encodeURIComponent(phone) + &quot;%0A&quot; +
      &quot;Appliance: &quot; + encodeURIComponent(appliance) + &quot;%0A&quot; +
      &quot;Problem: &quot; + encodeURIComponent(problem);


    const whatsappURL =
      &quot;https://wa.me/918097301783?text=&quot; + message;


    window.open(whatsappURL, &quot;_blank&quot;);

  });

&lt;/script&gt;

